{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "required": [
        "Type",
        "HttpMethod",
        "ResourceId",
        "RestApiId"
    ],
    "additionalProperties": false,
    "properties": {
        "Type": {
            "type": "string",
            "enum": [
                "HTTP",
                "AWS",
                "MOCK"
            ]
        },
        "HttpMethod": {
            "type": "string",
            "enum": [
                "DELETE",
                "GET",
                "HEAD",
                "OPTIONS",
                "PATCH",
                "POST",
                "PUT"
            ]
        },
        "ResourceId": {
            "type": "string",
            "pattern": "^[a-z0-9]+$"
        },
        "RestApiId": {
            "type": "string",
            "pattern": "^[a-z0-9]{10}$"
        },
        "CacheKeyParameters": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "CacheNamespace": {
            "type": "string"
        },
        "Credentials": {
            "type": "string"
        },
        "IntegrationHttpMethod": {
            "type": "string"
        },
        "RequestTemplates": {
            "type": "object",
            "properties": {},
            "patternProperties": {
                ".+": {
                    "type": "string"
                }
            },
            "additionalProperties": false
        },
        "RequestParameters": {
            "type": "object",
            "properties": {},
            "patternProperties": {
                "^integration\\.request\\.(querystring|path|header)\\..+$": {
                    "type": "string",
                    "pattern": "^(method\\.request\\.(querystring|header|path)\\..+)|('.*')$"
                }
            },
            "additionalProperties": false
        },
        "Uri": {
            "type": "string"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "required": [
        "DomainName"
    ],
    "properties": {
        "DomainName": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9\\-]+$"
        },
        "AccessPolicies": {
            "type": "string",
            "pattern": ".+"
        },
        "AdvancedOptions": {
            "type": "object",
            "patternProperties": {
                ".+": {
                    "type": "string",
                    "pattern": ".+"
                }
            },
            "additionalProperties": false
        },
        "EBSOptions": {
            "type": "object",
            "properties": {
                "EBSEnabled": {
                    "type": "string",
                    "enum": [
                        "true",
                        "false"
                    ]
                },
                "Iops": {
                    "type": "string",
                    "pattern": "^\\d+$"
                },
                "VolumeSize": {
                    "type": "string",
                    "pattern": "^\\d+$"
                },
                "VolumeType": {
                    "type": "string",
                    "enum": [
                        "standard",
                        "gp2",
                        "io1"
                    ]
                }
            },
            "additionalProperties": false
        },
        "ElasticsearchClusterConfig": {
            "type": "object",
            "properties": {
                "DedicatedMasterCount": {
                    "type": "string",
                    "pattern": "^\\d$"
                },
                "DedicatedMasterEnabled": {
                    "type": "string",
                    "enum": [
                        "true",
                        "false"
                    ]
                },
                "DedicatedMasterType": {
                    "$ref": "#/definitions/ElasticseachNodeType"
                },
                "InstanceCount": {
                    "type": "string",
                    "pattern": "^\\d$"
                },
                "InstanceType": {
                    "$ref": "#/definitions/ElasticseachNodeType"
                },
                "ZoneAwarenessEnabled": {
                    "type": "string",
                    "enum": [
                        "true",
                        "false"
                    ]
                }
            },
            "additionalProperties": false
        },
        "SnapshotOptions": {
            "type": "object",
            "properties": {
                "AutomatedSnapshotStartHour": {
                    "type": "string",
                    "pattern": "^\\d$"
                }
            },
            "additionalProperties": false
        }
    },
    "additionalProperties": false,
    "definitions": {
        "ElasticseachNodeType": {
            "type": "string",
            "enum": [
                "m3.medium.elasticsearch",
                "m3.large.elasticsearch",
                "m3.xlarge.elasticsearch",
                "m3.2xlarge.elasticsearch",
                "t2.micro.elasticsearch",
                "t2.small.elasticsearch",
                "t2.medium.elasticsearch",
                "r3.large.elasticsearch",
                "r3.xlarge.elasticsearch",
                "r3.2xlarge.elasticsearch",
                "r3.4xlarge.elasticsearch",
                "r3.8xlarge.elasticsearch",
                "i2.xlarge.elasticsearch",
                "i2.2xlarge.elasticsearch"
            ]
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema",
    "title": "Prerender Target",
    "type": "object",
    "properties": {
        "browserTarget": {
            "type": "string",
            "description": "Target to build.",
            "pattern": "^[^:\\s]+:[^:\\s]+(:[^\\s]+)?$"
        },
        "serverTarget": {
            "type": "string",
            "description": "Server target to use for prerendering the app.",
            "pattern": "^[^:\\s]+:[^:\\s]+(:[^\\s]+)?$"
        },
        "routesFile": {
            "type": "string",
            "description": "The path to a file containing routes separated by newlines."
        },
        "routes": {
            "type": "array",
            "description": "The routes to render.",
            "items": {
                "minItems": 1,
                "type": "string",
                "_uniqueItems": true
            },
            "default": []
        },
        "guessRoutes": {
            "type": "boolean",
            "description": "Whether or not the builder should extract routes and guess which paths to render.",
            "default": true
        },
        "numProcesses": {
            "type": "number",
            "description": "The number of cpus to use. Defaults to all but one.",
            "minimum": 1
        }
    },
    "required": [
        "browserTarget",
        "serverTarget"
    ],
    "anyOf": [
        {
            "required": [
                "routes"
            ]
        },
        {
            "required": [
                "routesFile"
            ]
        }
    ],
    "additionalProperties": false
}

{
    "$schema": "http://json-schema.org/draft-07/schema",
    "title": "SSR Dev Server Target",
    "description": "SSR Dev Server target options for Build Facade.",
    "type": "object",
    "properties": {
        "browserTarget": {
            "type": "string",
            "description": "Browser target to build.",
            "pattern": ".+:.+(:.+)?"
        },
        "serverTarget": {
            "type": "string",
            "description": "Server target to build.",
            "pattern": ".+:.+(:.+)?"
        },
        "host": {
            "type": "string",
            "description": "Host to listen on.",
            "default": "localhost"
        },
        "port": {
            "type": "number",
            "default": 4200,
            "description": "Port to start the development server at. Default is 4200. Pass 0 to get a dynamically assigned port."
        },
        "publicHost": {
            "type": "string",
            "description": "The URL that the browser client should use to connect to the development server. Use for a complex dev server setup, such as one with reverse proxies."
        },
        "open": {
            "type": "boolean",
            "description": "Opens the url in default browser.",
            "default": false,
            "alias": "o"
        },
        "progress": {
            "type": "boolean",
            "description": "Log progress to the console while building."
        },
        "inspect": {
            "type": "boolean",
            "description": "Launch the development server in inspector mode and listen on address and port '127.0.0.1:9229'.",
            "default": false
        }
    },
    "additionalProperties": false,
    "required": [
        "browserTarget",
        "serverTarget"
    ]
}

{
    "additionalProperties": false,
    "properties": {
        "appDir": {
            "default": "app",
            "description": "The name of the application directory.",
            "format": "path",
            "type": "string"
        },
        "appId": {
            "default": "serverApp",
            "description": "The appId to use withServerTransition.",
            "format": "html-selector",
            "type": "string"
        },
        "clientProject": {
            "$default": {
                "$source": "projectName"
            },
            "description": "Name of related client app.",
            "type": "string"
        },
        "main": {
            "default": "main.server.ts",
            "description": "The name of the main entry-point file.",
            "format": "path",
            "type": "string"
        },
        "rootModuleClassName": {
            "default": "AppServerModule",
            "description": "The name of the root module class.",
            "type": "string"
        },
        "rootModuleFileName": {
            "default": "app.server.module.ts",
            "description": "The name of the root module file",
            "format": "path",
            "type": "string"
        },
        "serverFileName": {
            "default": "server.ts",
            "description": "The name of the Express server file.",
            "type": "string"
        },
        "serverPort": {
            "default": 4000,
            "description": "The port for the Express server.",
            "type": "number"
        },
        "skipInstall": {
            "default": false,
            "description": "Skip installing dependency packages.",
            "type": "boolean"
        },
        "tsconfigFileName": {
            "default": "tsconfig.server",
            "description": "The name of the TypeScript configuration file.",
            "type": "string"
        }
    },
    "required": [
        "clientProject"
    ],
    "title": "Express Engine Install Options Schema",
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "windowSize": {
            "type": "object",
            "properties": {
