                    "minLength": 1
                }
            },
            "required": [
                "siteType",
                "url"
            ]
        },
        {
            "properties": {
                "siteType": {
                    "type": "string",
                    "enum": [
                        "html"
                    ]
                },
                "html": {
                    "type": "string",
                    "minLength": 1
                }
            },
            "required": [
                "siteType",
                "html"
            ]
