        "array": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "arrayComplex": {
            "type": "array",
            "items": {
                "title": "a",
                "type": "object",
                "properties": {
                    "foo": {
                        "type": "string"
                    }
                }
            }
        },
        "arrayChoice": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "title": "choiceA",
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                            "foo": {
                                "type": "string"
                            }
                        }
                    },
                    {
                        "title": "choiceB",
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                            "bar": {
                                "type": "string"
                            }
                        }
                    }
                ]
            }
        },
        "boolean": {
            "type": "boolean"
        },
        "choice": {
            "oneOf": [
                {
                    "title": "choiceA",
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "foo": {
                            "type": "string"
                        }
                    }
                },
                {
                    "title": "choiceB",
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "bar": {
                            "type": "string"
                        }
                    }
                }
            ]
        },
        "complex": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "foo": {
                    "type": "string"
                }
            }
        },
        "date": {
            "type": "string",
            "format": "date"
        },
        "dateTime": {
            "type": "string",
            "format": "date-time"
        },
        "duration": {
            "type": "string",
            "format": "duration"
        },
        "float": {
